"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { usePrice } from "@/hooks/usePrice";

interface Props {
  feed: "BTC" | "ETH";
}

const MAX_POINTS = 120;
const CHART_HEIGHT = 80;

export function MiniChart({ feed }: Props) {
  const { price } = usePrice(feed);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pointsRef = useRef<number[]>([]);
  const [currentPrice, setCurrentPrice] = useState(0);
  const [priceChange, setPriceChange] = useState(0);
  const initializedRef = useRef(false);

  // Fetch server-side cached history on mount
  useEffect(() => {
    if (initializedRef.current) return;
    initializedRef.current = true;

    fetch("/api/prices")
      .then((r) => r.json())
      .then((data) => {
        const history = data[feed] as number[];
        if (history && history.length > 0) {
          pointsRef.current = [...history];
          setCurrentPrice(history[history.length - 1]);
          if (history.length >= 2) {
            setPriceChange(((history[history.length - 1] - history[0]) / history[0]) * 100);
          }
        }
      })
      .catch(() => {});
  }, [feed]);

  // Collect live price points
  useEffect(() => {
    if (price <= 0) return;
    const pts = pointsRef.current;
    if (pts.length === 0 || pts[pts.length - 1] !== price) {
      pts.push(price);
      if (pts.length > MAX_POINTS) pts.shift();
    }
    setCurrentPrice(price);
    if (pts.length >= 2) {
      setPriceChange(((price - pts[0]) / pts[0]) * 100);
    }
  }, [price]);

  // Draw chart
  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);

    const w = rect.width;
    const h = rect.height;
    const pts = pointsRef.current;

    ctx.clearRect(0, 0, w, h);

    if (pts.length < 2) return;

    const min = Math.min(...pts);
    const max = Math.max(...pts);
    const range = max - min || 1;
    const padding = 8;
    const chartH = h - padding * 2;

    const isUp = pts[pts.length - 1] >= pts[0];
    const lineColor = isUp ? "#00e676" : "#ff1744";
    const fillColor = isUp ? "rgba(0, 230, 118, 0.08)" : "rgba(255, 23, 68, 0.08)";

    // Draw line
    ctx.beginPath();
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = 2;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";

    for (let i = 0; i < pts.length; i++) {
      const x = (i / (MAX_POINTS - 1)) * w;
      const y = padding + chartH - ((pts[i] - min) / range) * chartH;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Draw fill
    ctx.lineTo(((pts.length - 1) / (MAX_POINTS - 1)) * w, h);
    ctx.lineTo(0, h);
    ctx.closePath();
    ctx.fillStyle = fillColor;
    ctx.fill();

    // Glow dot at latest point
    const lastX = ((pts.length - 1) / (MAX_POINTS - 1)) * w;
    const lastY = padding + chartH - ((pts[pts.length - 1] - min) / range) * chartH;

    ctx.beginPath();
    ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
    ctx.fillStyle = lineColor;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(lastX, lastY, 8, 0, Math.PI * 2);
    ctx.fillStyle = isUp ? "rgba(0, 230, 118, 0.3)" : "rgba(255, 23, 68, 0.3)";
    ctx.fill();
  }, []);

  useEffect(() => {
    draw();
    const id = setInterval(draw, 500);
    return () => clearInterval(id);
  }, [draw, currentPrice]);

  const isUp = priceChange >= 0;
  const icon = feed === "BTC" ? "₿" : "Ξ";

  return (
    <div className="rounded-2xl border border-border bg-bg-card overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2.5">
        <div className="flex items-center gap-2">
          <span className="text-base">{icon}</span>
          <span className="text-xs font-semibold text-text-dim uppercase tracking-wide">{feed}/USD</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-sm font-mono font-bold text-text-bright">
            ${currentPrice > 0 ? currentPrice.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : "—"}
          </span>
          {pointsRef.current.length >= 2 && (
            <span className={`text-xs font-semibold ${isUp ? "text-up" : "text-down"}`}>
              {isUp ? "▲" : "▼"} {Math.abs(priceChange).toFixed(3)}%
            </span>
          )}
        </div>
      </div>
      <canvas
        ref={canvasRef}
        className="w-full"
        style={{ height: CHART_HEIGHT, display: "block" }}
      />
    </div>
  );
}
