"use client";

import { useEffect, useState, useRef } from "react";
import { createPublicClient, http } from "viem";
import { megaethTestnet, ADDRESSES, ORACLE_ABI } from "@/lib/contract";

interface PriceData {
  price: number;
  prevPrice: number;
  timestamp: number;
}

export function usePrice(feed: "BTC" | "ETH") {
  const [data, setData] = useState<PriceData>({ price: 0, prevPrice: 0, timestamp: 0 });
  const clientRef = useRef<ReturnType<typeof createPublicClient> | null>(null);

  useEffect(() => {
    if (!clientRef.current) {
      clientRef.current = createPublicClient({
        chain: megaethTestnet,
        transport: http(megaethTestnet.rpcUrls.default.http[0]),
      });
    }
    const client = clientRef.current;
    const oracle = feed === "BTC" ? ADDRESSES.btcOracle : ADDRESSES.ethOracle;

    const fetchPrice = async () => {
      try {
        const result = await client.readContract({
          address: oracle,
          abi: ORACLE_ABI,
          functionName: "latestRoundData",
        });
        const [, answer, , updatedAt] = result;
        const price = Number(answer) / 1e8;
        setData((prev) => ({
          price,
          prevPrice: prev.price || price,
          timestamp: Number(updatedAt),
        }));
      } catch (e) {
        console.error("Price fetch error:", e);
      }
    };

    fetchPrice();
    const id = setInterval(fetchPrice, 500);
    return () => clearInterval(id);
  }, [feed]);

  return data;
}
